export const levelText={
 es:[
 {short:'Salón de la Declaración',title:'Una declaración toma forma',place:'Seneca Falls, Nueva York',artifact:'Insignia de la Voz',intro:'En este salón, personas comunes hacen algo extraordinario: nombran la injusticia en público. Reúne las pruebas que usaron.',facts:[{tag:'FUENTE PRIMARIA',title:'Declaración de Sentimientos',text:'«Sostenemos que estas verdades son evidentes: que todos los hombres y las mujeres son creados iguales».',note:'El texto imitó deliberadamente la Declaración de Independencia para vincular los derechos de las mujeres con los ideales fundacionales.'},{tag:'LA EXIGENCIA',title:'El derecho al voto',text:'El documento enumeró agravios y afirmó el «sagrado derecho al sufragio».',note:'El voto era polémico incluso entre reformistas, pero Frederick Douglass defendió la resolución.'},{tag:'LA COALICIÓN',title:'Firmas y apoyo',text:'Sesenta y ocho mujeres y treinta y dos hombres firmaron tras dos días de debate.',note:'Firmar convirtió una convicción privada en un compromiso público.'}],question:'¿Qué prueba apoya mejor que la convención conectó el voto con los ideales fundacionales?',answers:['La reunión duró dos días.','La declaración repitió «evidentes» y «creados iguales».','Cien personas firmaron el documento.'],hint:'Busca lenguaje tomado de un documento fundacional famoso.',explain:'El eco de la Declaración de Independencia sostenía que su promesa de igualdad debía incluir a las mujeres.'},
 {short:'Cruce de Coaliciones',title:'Muchas voces, trabajo compartido',place:'Tribunas, imprentas y clubes',artifact:'Llave de la Coalición',intro:'El movimiento crece mediante discursos, periódicos, convenciones, clubes y peticiones. Sus líderes aportan experiencias distintas y no siempre coinciden.',facts:[{tag:'VOZ',title:'Sojourner Truth',text:'Nacida en esclavitud en Nueva York, Truth se convirtió en una poderosa oradora por la abolición y los derechos de las mujeres.',note:'Su discurso de Akron de 1851 existe en versiones diferentes: importa preguntar quién registró una fuente y cuándo.'},{tag:'PRENSA',title:'Frances E. W. Harper',text:'Harper insistió en que raza, género y justicia económica no podían separarse.',note:'En 1866 dijo a los reformistas: «Todos estamos unidos».'},{tag:'CLUBES',title:'Mary Church Terrell',text:'Terrell ayudó a fundar la Asociación Nacional de Mujeres de Color.',note:'Los clubes de mujeres negras organizaron el sufragio mientras enfrentaban racismo dentro y fuera del movimiento.'}],question:'¿Qué plan utiliza la mayor variedad de estrategias para llegar a quienes quedaron fuera?',answers:['Esperar a una sola líder famosa.','Publicar, crear clubes locales, organizar charlas y circular peticiones.','Convencer solamente a legisladores nacionales.'],hint:'Las coaliciones crecen por muchos canales y relaciones locales.',explain:'La prensa, los clubes, las giras y las peticiones permitieron llegar a comunidades distintas.'},
 {short:'Ruta de Estrategias Estatales',title:'Muchos caminos hacia el voto',place:'De Wyoming a Texas',artifact:'Estrella Estatal',intro:'Antes de una enmienda federal, las organizadoras probaron estrategias estatales. El avance fue desigual.',facts:[{tag:'VICTORIA DEL OESTE',title:'Territorio de Wyoming, 1869',text:'Wyoming concedió el voto a las mujeres en 1869 y lo mantuvo al convertirse en estado.',note:'Las victorias del oeste mostraron que el voto femenino funcionaba en la práctica.'},{tag:'CAMPAÑA ESTATAL',title:'Peticiones y referendos',text:'Las organizadoras reunieron firmas, presionaron a legisladores y participaron en referendos.',note:'El trabajo estatal desarrolló capacidad local incluso cuando se perdía.'},{tag:'TEXAS',title:'Primarias de 1918',text:'Las mujeres de Texas ganaron el voto en primarias si se registraban al menos 15 días antes.',note:'Minnie Fisher Cunningham y miles de voluntarias organizaron una campaña rápida.'}],question:'Una organizadora de Texas tiene pocas semanas. ¿Qué debe priorizar?',answers:['Esperar la enmienda federal.','Registrar votantes de inmediato y explicar el plazo de 15 días.','Trasladar la campaña a Wyoming.'],hint:'Un derecho en papel importa si las personas pueden cumplir las reglas a tiempo.',explain:'La campaña unió la victoria legal con un registro urgente para que las mujeres pudieran votar.'},
 {short:'Carrera de Ratificación',title:'Treinta y seis estados',place:'Del Congreso a Tennessee',artifact:'Sello de la 19.ª Enmienda',intro:'El Congreso aprobó la enmienda. Ahora tres cuartas partes de los estados deben ratificarla.',facts:[{tag:'PASO 1',title:'El Congreso propone',text:'El 4 de junio de 1919, el Senado se unió a la Cámara para aprobar la propuesta.',note:'Proponer no es ratificar: el Congreso envió el texto a los estados.'},{tag:'PASO 2',title:'Los estados deciden',text:'En el verano de 1920, treinta y cinco estados habían ratificado. Faltaba uno.',note:'Las activistas viajaron, escribieron y siguieron las votaciones.'},{tag:'PASO 3',title:'Tennessee, 1920',text:'Tennessee fue el estado 36 el 18 de agosto. La certificación llegó el 26.',note:'La votación fue muy reñida; el hito surgió de años de organización.'}],question:'Ordena los pasos constitucionales finales.',answers:['Certificación → ratificación → propuesta','Propuesta del Congreso → 36 estados ratifican → certificación','Ratificación → certificación → propuesta'],hint:'El Congreso propone; los estados ratifican; el gobierno certifica.',explain:'La enmienda pasó de la propuesta a la aprobación de tres cuartas partes y luego a la certificación.'},
 {short:'Puerta de la Igualdad',title:'Un hito, no un final',place:'El camino inconcluso',artifact:'Antorcha de la Igualdad',intro:'La 19.ª Enmienda prohibió discriminar por sexo al votar, pero otras barreras siguieron bloqueando a muchas personas.',facts:[{tag:'BARRERA',title:'Restricciones de ciudadanía',text:'A muchos indígenas se les negó la ciudadanía estadounidense hasta 1924; después continuaron leyes discriminatorias.',note:'La ciudadanía no garantizaba automáticamente el acceso al registro o al voto.'},{tag:'BARRERA',title:'Jim Crow y primarias blancas',text:'Impuestos, pruebas, violencia y primarias solo para blancos suprimieron el voto negro.',note:'Activistas negros desafiaron estos sistemas durante décadas.'},{tag:'RESPUESTA',title:'Ley de Derecho al Voto, 1965',text:'La ley dio al gobierno federal herramientas más fuertes contra la discriminación racial al votar.',note:'El acceso siguió cambiando mediante leyes, tribunales y organización.'}],question:'¿Qué conclusión está mejor respaldada?',answers:['La enmienda garantizó inmediatamente el mismo acceso a todas las personas.','La enmienda no importó porque quedaron barreras.','Fue un gran hito constitucional, pero las barreras raciales y de ciudadanía dejaron el acceso inconcluso.'],hint:'Una buena explicación reconoce el cambio real y sus límites.',explain:'La enmienda transformó la Constitución, pero no eliminó las barreras raciales, de ciudadanía o administrativas.'}
 ],
 vi:[],ar:[],hi:[],ur:[],zh:[]
};

