levelText.vi=[
 {short:'Sảnh Tuyên ngôn',title:'Một bản tuyên ngôn thành hình',place:'Seneca Falls, New York',artifact:'Huy hiệu Tiếng nói',intro:'Trong hội trường này, người dân công khai gọi tên bất công. Hãy thu thập bằng chứng họ đã dùng.',facts:[{tag:'NGUỒN GỐC',title:'Tuyên ngôn về Tình cảm',text:'“Chúng tôi tin những chân lý này là hiển nhiên: mọi nam giới và phụ nữ đều sinh ra bình đẳng.”',note:'Văn bản cố ý lặp lại Tuyên ngôn Độc lập để nối quyền phụ nữ với lý tưởng lập quốc.'},{tag:'YÊU CẦU',title:'Quyền bầu cử',text:'Văn bản liệt kê bất công và khẳng định quyền thiêng liêng được bỏ phiếu.',note:'Frederick Douglass đã mạnh mẽ ủng hộ nghị quyết gây tranh luận này.'},{tag:'LIÊN MINH',title:'Chữ ký và ủng hộ',text:'Sáu mươi tám phụ nữ và ba mươi hai nam giới đã ký sau hai ngày thảo luận.',note:'Chữ ký biến niềm tin riêng thành cam kết công khai.'}],question:'Bằng chứng nào cho thấy hội nghị liên hệ quyền bầu cử với lý tưởng lập quốc?',answers:['Cuộc họp kéo dài hai ngày.','Tuyên ngôn lặp lại “hiển nhiên” và “sinh ra bình đẳng”.','Một trăm người ký văn bản.'],hint:'Tìm ngôn ngữ mượn từ một văn kiện lập quốc nổi tiếng.',explain:'Việc nhắc lại Tuyên ngôn Độc lập khẳng định lời hứa bình đẳng phải bao gồm phụ nữ.'},
 {short:'Ngã tư Liên minh',title:'Nhiều tiếng nói, cùng hành động',place:'Diễn đàn, báo chí và câu lạc bộ',artifact:'Chìa khóa Liên minh',intro:'Phong trào phát triển qua diễn thuyết, báo chí, hội nghị, câu lạc bộ và kiến nghị.',facts:[{tag:'TIẾNG NÓI',title:'Sojourner Truth',text:'Sinh ra trong cảnh nô lệ, Truth trở thành diễn giả mạnh mẽ cho phong trào bãi nô và quyền phụ nữ.',note:'Bài nói năm 1851 còn nhiều phiên bản, nhắc ta hỏi ai ghi nguồn và khi nào.'},{tag:'BÁO CHÍ',title:'Frances E. W. Harper',text:'Harper nhấn mạnh rằng chủng tộc, giới và công bằng kinh tế không thể tách rời.',note:'Năm 1866 bà nói: “Tất cả chúng ta đều gắn bó với nhau.”'},{tag:'CÂU LẠC BỘ',title:'Mary Church Terrell',text:'Terrell góp phần thành lập Hiệp hội Phụ nữ Da màu Quốc gia.',note:'Các câu lạc bộ phụ nữ Da đen tổ chức đòi quyền bầu cử đồng thời chống phân biệt chủng tộc.'}],question:'Kế hoạch nào dùng nhiều chiến lược nhất để tiếp cận người bị loại trừ?',answers:['Chờ một lãnh đạo nổi tiếng.','Xuất bản báo, lập câu lạc bộ, tổ chức diễn thuyết và kiến nghị.','Chỉ thuyết phục nhà lập pháp quốc gia.'],hint:'Liên minh phát triển qua nhiều kênh và quan hệ địa phương.',explain:'Báo chí, câu lạc bộ, diễn thuyết và kiến nghị giúp tiếp cận nhiều cộng đồng.'},
 {short:'Đường Chiến lược Tiểu bang',title:'Nhiều con đường đến lá phiếu',place:'Từ Wyoming đến Texas',artifact:'Ngôi sao Tiểu bang',intro:'Trước tu chính án liên bang, các nhà tổ chức thử chiến lược theo từng tiểu bang.',facts:[{tag:'THẮNG LỢI MIỀN TÂY',title:'Wyoming, 1869',text:'Wyoming trao quyền bầu cử cho phụ nữ năm 1869 và giữ quyền đó khi thành tiểu bang.',note:'Thắng lợi miền Tây chứng minh quyền bầu cử của phụ nữ có hiệu quả.'},{tag:'CHIẾN DỊCH',title:'Kiến nghị và trưng cầu',text:'Họ thu thập chữ ký, vận động nghị sĩ và tham gia trưng cầu toàn tiểu bang.',note:'Công việc địa phương xây dựng năng lực ngay cả khi thất bại.'},{tag:'TEXAS',title:'Bầu cử sơ bộ 1918',text:'Phụ nữ Texas được bỏ phiếu sơ bộ nếu đăng ký trước ít nhất 15 ngày.',note:'Hàng nghìn tình nguyện viên tổ chức chiến dịch đăng ký khẩn trương.'}],question:'Một nhà tổ chức Texas chỉ còn vài tuần. Cần ưu tiên gì?',answers:['Chờ tu chính án liên bang.','Đăng ký ngay và giải thích rõ hạn 15 ngày.','Chuyển chiến dịch đến Wyoming.'],hint:'Quyền trên giấy chỉ có ý nghĩa khi người dân kịp đáp ứng quy định.',explain:'Các nhà tổ chức kết hợp thắng lợi pháp lý với việc đăng ký khẩn cấp.'},
 {short:'Cuộc đua Phê chuẩn',title:'Ba mươi sáu tiểu bang',place:'Từ Quốc hội đến Tennessee',artifact:'Ấn Tu chính án 19',intro:'Quốc hội đã thông qua đề xuất. Giờ ba phần tư số tiểu bang phải phê chuẩn.',facts:[{tag:'BƯỚC 1',title:'Quốc hội đề xuất',text:'Ngày 4 tháng 6 năm 1919, Thượng viện cùng Hạ viện thông qua đề xuất.',note:'Đề xuất chưa phải phê chuẩn; văn bản được gửi đến các tiểu bang.'},{tag:'BƯỚC 2',title:'Tiểu bang quyết định',text:'Đến hè 1920, 35 tiểu bang đã phê chuẩn. Cần thêm một.',note:'Các nhà vận động đi lại, viết thư và theo dõi phiếu.'},{tag:'BƯỚC 3',title:'Tennessee, 1920',text:'Tennessee trở thành tiểu bang thứ 36 ngày 18 tháng 8; chứng nhận vào ngày 26.',note:'Cuộc bỏ phiếu rất sít sao sau nhiều năm tổ chức.'}],question:'Sắp xếp đúng các bước hiến pháp cuối cùng.',answers:['Chứng nhận → phê chuẩn → đề xuất','Quốc hội đề xuất → 36 tiểu bang phê chuẩn → chứng nhận','Phê chuẩn → chứng nhận → đề xuất'],hint:'Quốc hội đề xuất; tiểu bang phê chuẩn; liên bang chứng nhận.',explain:'Tu chính án đi từ đề xuất, qua phê chuẩn của ba phần tư tiểu bang, đến chứng nhận.'},
 {short:'Cổng Bình đẳng',title:'Cột mốc, chưa phải kết thúc',place:'Con đường còn dang dở',artifact:'Ngọn đuốc Bình đẳng',intro:'Tu chính án 19 cấm phân biệt vì giới tính khi bỏ phiếu, nhưng nhiều rào cản khác vẫn tồn tại.',facts:[{tag:'RÀO CẢN',title:'Hạn chế quốc tịch',text:'Nhiều người Mỹ bản địa bị từ chối quốc tịch đến năm 1924; luật phân biệt vẫn tiếp diễn.',note:'Quốc tịch không tự động bảo đảm quyền đăng ký hay bỏ phiếu.'},{tag:'RÀO CẢN',title:'Jim Crow và sơ bộ da trắng',text:'Thuế, bài kiểm tra, bạo lực và bầu cử chỉ dành cho người da trắng đàn áp cử tri Da đen.',note:'Các nhà hoạt động Da đen đấu tranh suốt nhiều thập kỷ.'},{tag:'PHẢN ỨNG',title:'Đạo luật Quyền Bầu cử 1965',text:'Luật trao công cụ liên bang mạnh hơn để chống phân biệt chủng tộc trong bầu cử.',note:'Quyền tiếp cận tiếp tục thay đổi qua luật, tòa án và tổ chức.'}],question:'Kết luận nào được bằng chứng hỗ trợ tốt nhất?',answers:['Tu chính án lập tức bảo đảm quyền bình đẳng cho mọi người.','Tu chính án không quan trọng vì rào cản vẫn còn.','Đó là cột mốc lớn, nhưng rào cản chủng tộc và quốc tịch khiến quyền tiếp cận chưa hoàn tất.'],hint:'Giải thích tốt thừa nhận cả thay đổi thật và giới hạn thật.',explain:'Tu chính án thay đổi Hiến pháp nhưng không xóa bỏ rào cản về chủng tộc, quốc tịch và thủ tục.'}
];
levelText.zh=[
 {short:'宣言大厅',title:'一份宣言的诞生',place:'纽约州塞尼卡福尔斯',artifact:'发声徽章',intro:'普通人在这里公开指出不公。收集他们用来提出主张的证据。',facts:[{tag:'一手资料',title:'《感伤宣言》',text:'“我们认为这些真理是不言而喻的：所有男人和女人生而平等。”',note:'起草者有意呼应《独立宣言》，把妇女权利与建国理想联系起来。'},{tag:'核心诉求',title:'选举权',text:'文件列举不公，并主张妇女享有神圣的选举权。',note:'即使在改革者中，这项主张也有争议；弗雷德里克·道格拉斯坚决支持。'},{tag:'联盟',title:'签名与支持',text:'经过两天讨论，68名妇女和32名男子签署了宣言。',note:'签名把个人信念变成公开承诺。'}],question:'哪项证据最能说明大会把投票权与美国建国理想联系起来？',answers:['会议持续了两天。','宣言呼应了“不言而喻”和“生而平等”。','共有一百人签名。'],hint:'寻找借用自著名建国文献的语言。',explain:'对《独立宣言》的呼应说明，平等的承诺也应包括妇女。'},
 {short:'联盟十字路口',title:'多种声音，共同努力',place:'讲台、印刷所与社团',artifact:'联盟钥匙',intro:'运动通过演讲、报纸、会议、社团和请愿不断扩大。不同领导者并非总是意见一致。',facts:[{tag:'声音',title:'索杰纳·特鲁思',text:'特鲁思出生于纽约的奴隶制度下，后来成为废奴和妇女权利的有力演说家。',note:'她1851年的演讲有不同版本，提醒我们追问资料由谁、何时记录。'},{tag:'出版',title:'弗朗西丝·哈珀',text:'哈珀坚持认为种族、性别与经济正义不可分割。',note:'1866年，她说：“我们所有人都紧密相连。”'},{tag:'社团',title:'玛丽·丘奇·特雷尔',text:'特雷尔参与创立全国有色妇女协会。',note:'黑人妇女社团争取选举权，同时面对运动内外的种族歧视。'}],question:'哪项计划能用最多样的策略接触被大会排除的人？',answers:['等待一位著名领袖演讲。','出版报纸、建立地方社团、举办演讲并发起请愿。','只说服国家立法者。'],hint:'联盟通过多种渠道和地方关系成长。',explain:'出版、社团、巡回演讲和请愿能触及不同社群。'},
 {short:'州级策略之路',title:'通往选票的多条道路',place:'从怀俄明到得克萨斯',artifact:'州之星',intro:'在联邦修正案之前，组织者尝试州级策略，进展并不均衡。',facts:[{tag:'西部胜利',title:'怀俄明领地，1869',text:'怀俄明1869年给予妇女投票权，1890年建州时继续保留。',note:'西部的胜利证明妇女投票在实践中可行。'},{tag:'州级运动',title:'请愿与公投',text:'组织者收集签名、游说议员并参与全州公投。',note:'即使公投失败，地方组织能力仍得到发展。'},{tag:'得克萨斯',title:'1918年初选权',text:'得州妇女获得初选投票权，但须至少提前15天登记。',note:'数千名志愿者迅速开展登记行动。'}],question:'得州组织者只剩几周，应优先做什么？',answers:['等待联邦修正案。','立即登记选民并说明15天期限。','把运动转移到怀俄明。'],hint:'纸面权利只有在人们及时满足规则时才有意义。',explain:'组织者把法律胜利与紧急登记结合起来，使妇女真正能够投票。'},
 {short:'批准冲刺',title:'三十六个州',place:'从国会到田纳西',artifact:'第十九修正案印章',intro:'国会已经通过提案。现在需要四分之三的州批准。',facts:[{tag:'第一步',title:'国会提出',text:'1919年6月4日，参议院与众议院一起通过修正案提案。',note:'提出不等于批准；国会把文本送交各州。'},{tag:'第二步',title:'各州决定',text:'到1920年夏，35个州已经批准，还差一个。',note:'活动家旅行、写信、游说并追踪表决。'},{tag:'第三步',title:'田纳西，1920',text:'8月18日田纳西成为第36州；8月26日完成认证。',note:'表决极其接近，成果来自多年的组织。'}],question:'按正确顺序排列最后的宪法步骤。',answers:['认证 → 州批准 → 国会提出','国会提出 → 36州批准 → 认证','州批准 → 认证 → 国会提出'],hint:'国会提出；各州批准；联邦政府认证。',explain:'修正案经历国会提出、四分之三州批准，最后由联邦认证。'},
 {short:'平等之门',title:'里程碑，而非终点',place:'尚未完成的道路',artifact:'平等火炬',intro:'第十九修正案禁止以性别为由剥夺投票权，但其他障碍仍阻挡许多公民。',facts:[{tag:'障碍',title:'公民身份限制',text:'许多美洲原住民直到1924年才获美国公民身份；歧视性州法此后仍存在。',note:'公民身份并不自动保证登记或投票机会。'},{tag:'障碍',title:'吉姆·克劳法与白人初选',text:'人头税、识字测试、暴力和白人专属初选压制黑人投票。',note:'黑人活动家在法院、社区和国会抗争了数十年。'},{tag:'回应',title:'1965年《投票权法》',text:'该法赋予联邦政府更有力的工具，打击投票中的种族歧视。',note:'投票机会继续通过法律、法院裁决和组织行动而变化。'}],question:'哪项结论最受证据支持？',answers:['修正案立即保证所有成年人平等投票。','因为障碍仍在，所以修正案毫无意义。','它是重大宪法里程碑，但种族和公民身份障碍使投票机会仍未完善。'],hint:'有力的历史解释既承认真正的变化，也承认真正的局限。',explain:'修正案改变了宪法，但没有消除种族、公民身份或行政障碍。'}
];
// Arabic, Hindi, and Urdu chapters. Answer order matches the English `levels`
// array in main.jsx, because `correct` is read from the English record.
levelText.ar=[
 {short:'قاعة الإعلان',title:'إعلان يتشكّل',place:'سينيكا فولز، نيويورك',artifact:'شارة الصوت',intro:'داخل هذه القاعة يفعل أناسٌ عاديون شيئًا استثنائيًا: تسمية الظلم علنًا. اجمع الأدلة التي استخدموها لبناء حجّتهم.',facts:[{tag:'مصدر أوّلي',title:'إعلان المبادئ',text:'«نعتبر هذه الحقائق بديهية: أن جميع الرجال والنساء خُلقوا متساوين».',note:'حاكى الكتّاب إعلان الاستقلال عمدًا لربط حقوق النساء بالمثل التأسيسية للأمة.'},{tag:'المطلب',title:'حق الاقتراع',text:'عدّد الإعلان المظالم ثم أكّد أن للنساء «الحق المقدّس في الاقتراع».',note:'كان التصويت مثيرًا للجدل حتى بين الإصلاحيين، لكن فريدريك دوغلاس دافع بقوة عن القرار.'},{tag:'التحالف',title:'التوقيعات والدعم',text:'وقّع الإعلان ثمانٍ وستون امرأة واثنان وثلاثون رجلًا بعد يومين من النقاش.',note:'التوقيع حوّل قناعة خاصة إلى التزام علني.'}],question:'أي دليل يدعم على أفضل وجه الادعاء بأن المؤتمر ربط حق التصويت بالمثل التأسيسية الأمريكية؟',answers:['استمر الاجتماع يومين.','ردّد الإعلان عبارتَي «بديهية» و«خُلقوا متساوين».','وقّع المستند مئة شخص.'],hint:'ابحث عن لغة مقتبسة من وثيقة تأسيسية شهيرة.',explain:'المحاكاة المتعمَّدة لإعلان الاستقلال جادلت بأن وعده بالمساواة ينبغي أن يشمل النساء.'},
 {short:'مفترق التحالف',title:'أصوات كثيرة، عمل مشترك',place:'المنابر والمطابع وقاعات الأندية',artifact:'مفتاح التحالف',intro:'تنمو الحركة عبر الخطب والصحف والمؤتمرات والأندية والعرائض. يجلب القادة المختلفون خبرات مختلفة، ولا يتفقون دائمًا.',facts:[{tag:'صوت',title:'سوجورنر تروث',text:'وُلدت تروث في العبودية في نيويورك، وصارت خطيبة مؤثرة لإلغاء الرق وحقوق النساء.',note:'بقي خطابها في أكرون عام ١٨٥١ في روايات متباينة، وهو تذكير بأن نسأل من دوّن المصدر ومتى.'},{tag:'صحافة',title:'فرانسيس إ. و. هاربر',text:'أصرّت الكاتبة والمحاضِرة هاربر على أن العرق والنوع والعدالة الاقتصادية لا يمكن فصلها.',note:'قالت للإصلاحيين عام ١٨٦٦: «نحن جميعًا مرتبطون معًا».'},{tag:'أندية',title:'ماري تشيرش تيريل',text:'شاركت تيريل في تأسيس الرابطة الوطنية للنساء الملوّنات، وشعارها «نرتقي ونحن نرفع غيرنا».',note:'نظّمت أندية النساء السود للاقتراع بينما واجهت العنصرية داخل الحركة وخارجها.'}],question:'يريد تحالف الوصول إلى من استُبعدوا من المؤتمرات الكبرى. أي خطة تستخدم أوسع مدى من استراتيجيات الحركة؟',answers:['انتظار زعيم مشهور واحد ليتكلم.','إصدار صحيفة وبناء أندية محلية واستضافة متحدثين وتعميم العرائض.','التركيز فقط على إقناع المشرّعين الوطنيين.'],hint:'تنمو التحالفات عبر قنوات كثيرة وعلاقات محلية.',explain:'أتاحت المطبوعات والأندية والجولات الخطابية والعرائض للمنظِّمين الوصول إلى مجتمعات متمايزة وبناء شبكات دائمة.'},
 {short:'درب استراتيجيات الولايات',title:'طرق كثيرة إلى صندوق الاقتراع',place:'من وايومنغ إلى تكساس',artifact:'نجمة الولاية',intro:'قبل التعديل الفيدرالي، اختبر المنظِّمون استراتيجيات على مستوى الولايات. تقدّم الدرب بتفاوت: أحيانًا إلى الأمام، وأحيانًا حول عائق.',facts:[{tag:'انتصار غربي',title:'إقليم وايومنغ، ١٨٦٩',text:'منحت وايومنغ النساء حق التصويت عام ١٨٦٩ وأبقته حين صارت ولاية عام ١٨٩٠.',note:'وفّرت الانتصارات الغربية دليلًا على أن تصويت النساء ناجح عمليًا.'},{tag:'حملة الولاية',title:'العرائض والاستفتاءات',text:'جمع المنظِّمون التوقيعات، وضغطوا على المشرّعين، وخاضوا حملات في استفتاءات على مستوى الولاية.',note:'بنى العمل ولايةً ولايةً مهارة تنظيمية محلية، حتى حين سقط الاستفتاء.'},{tag:'تكساس',title:'اقتراع الانتخابات التمهيدية، ١٩١٨',text:'نالت نساء تكساس حق التصويت في الانتخابات التمهيدية، شرط التسجيل قبل يوم الاقتراع بخمسة عشر يومًا على الأقل.',note:'نظّمت ميني فيشر كننغهام وآلاف المتطوعات حملة تسجيل سريعة.'}],question:'أمام منظِّمة في تكساس أسابيع قليلة فقط قبل انتخابات ١٩١٨ التمهيدية. ما الذي ينبغي أن تعطيه الحملة الأولوية؟',answers:['انتظار التعديل الفيدرالي.','إطلاق حملة تسجيل فورية وشرح مهلة الخمسة عشر يومًا بوضوح.','نقل الحملة إلى وايومنغ.'],hint:'الحق على الورق لا يهم إلا إذا استطاع الناس استيفاء قواعد الوصول في الوقت المناسب.',explain:'قرن منظِّمو تكساس الانتصار القانوني بعمل تسجيل محلي عاجل حتى تتمكن المؤهَّلات فعلًا من الإدلاء بأصواتهن.'},
 {short:'سباق التصديق',title:'ست وثلاثون ولاية',place:'من الكونغرس إلى تينيسي',artifact:'ختم التعديل التاسع عشر',intro:'أقرّ الكونغرس التعديل. الآن يجب أن تصدّق عليه ثلاثة أرباع الولايات. اتبع المسار الدستوري، ثم افتح تصويت تينيسي الحاسم.',facts:[{tag:'الخطوة ١',title:'الكونغرس يقترح',text:'في ٤ يونيو ١٩١٩، انضم مجلس الشيوخ إلى مجلس النواب في إقرار التعديل المقترح.',note:'الاقتراح ليس تصديقًا. أرسل الكونغرس النص إلى الولايات.'},{tag:'الخطوة ٢',title:'الولايات تقرّر',text:'بحلول صيف ١٩٢٠ كانت خمس وثلاثون ولاية قد صدّقت. وكانت الحاجة إلى واحدة أخرى.',note:'سافر النشطاء وكتبوا الرسائل وضغطوا وتتبّعوا الأصوات في أنحاء البلاد.'},{tag:'الخطوة ٣',title:'تينيسي، ١٩٢٠',text:'صارت تينيسي الولاية السادسة والثلاثين المصدِّقة في ١٨ أغسطس. وتلا ذلك التوثيق في ٢٦ أغسطس.',note:'كان تصويت مجلس الولاية متقاربًا للغاية. نشأ معلم دستوري من سنوات من التنظيم.'}],question:'رتّب الخطوات الدستورية الأخيرة بالترتيب الصحيح.',answers:['التوثيق ← تصديق الولايات ← اقتراح الكونغرس','اقتراح الكونغرس ← تصديق ٣٦ ولاية ← التوثيق','تصديق الولايات ← التوثيق ← اقتراح الكونغرس'],hint:'الكونغرس يقترح؛ والولايات تصدّق؛ والحكومة الفيدرالية توثّق.',explain:'انتقل التعديل من اقتراح الكونغرس، إلى موافقة ثلاثة أرباع الولايات، إلى التوثيق الفيدرالي.'},
 {short:'بوابة المساواة',title:'محطة، لا نهاية',place:'الطريق غير المكتمل',artifact:'شعلة المساواة',intro:'منع التعديل التاسع عشر التمييز في التصويت على أساس الجنس. لكن عوائق أخرى ظلّت تسدّ الطريق أمام كثيرين. يطلب منا التاريخ أن نحمل التقدّم والعمل غير المكتمل معًا.',facts:[{tag:'عائق',title:'قيود المواطنة',text:'حُرم كثير من الأمريكيين الأصليين من الجنسية الأمريكية حتى ١٩٢٤، واستمرت قوانين الولايات التمييزية بعد ذلك.',note:'لم تضمن المواطنة تلقائيًا الوصول إلى التسجيل أو صندوق الاقتراع.'},{tag:'عائق',title:'جيم كرو والانتخابات التمهيدية البيضاء',text:'قمعت ضرائب الاقتراع واختبارات القراءة والعنف والانتخابات التمهيدية المقصورة على البيض تصويت السود، خاصة في الجنوب.',note:'تحدّى النشطاء السود هذه الأنظمة عقودًا في المحاكم والمجتمعات والكونغرس.'},{tag:'استجابة',title:'قانون حقوق التصويت، ١٩٦٥',text:'منح القانون الحكومة الفيدرالية أدوات أقوى ضد التمييز العنصري في التصويت.',note:'ظل الوصول يتغير عبر القوانين وقرارات المحاكم والتنظيم والمشاركة العامة.'}],question:'أي استنتاج تدعمه الأدلة على أفضل وجه؟',answers:['ضمن التعديل التاسع عشر فورًا لكل بالغ أمريكي وصولًا متساويًا إلى الاقتراع.','كان التعديل التاسع عشر غير مهم لأن العوائق بقيت.','كان التعديل التاسع عشر معلمًا دستوريًا كبيرًا، بينما تركت عوائق المواطنة والعرق الوصول إلى التصويت غير مكتمل.'],hint:'التفسيرات التاريخية القوية تستطيع الاعتراف بالتغيير الحقيقي والقيود الحقيقية معًا.',explain:'غيّر التعديل الدستور، لكنه لم يمحُ العوائق القائمة على العرق أو المواطنة أو الإدارة التمييزية.'}
];
levelText.hi=[
 {short:'घोषणा भवन',title:'एक घोषणापत्र आकार लेता है',place:'सेनेका फॉल्स, न्यूयॉर्क',artifact:'वाणी बैज',intro:'इस सभा भवन में साधारण लोग असाधारण काम कर रहे हैं: अन्याय को सार्वजनिक रूप से नाम देना। वे साक्ष्य जुटाएँ जिनसे उन्होंने अपनी बात रखी।',facts:[{tag:'प्राथमिक स्रोत',title:'भावनाओं की घोषणा',text:'“हम इन सत्यों को स्वतःस्पष्ट मानते हैं: कि सभी पुरुष और स्त्रियाँ समान बनाए गए हैं।”',note:'लेखकों ने जानबूझकर स्वतंत्रता की घोषणा की प्रतिध्वनि की, ताकि स्त्रियों के अधिकार राष्ट्र के संस्थापक आदर्शों से जुड़ें।'},{tag:'माँग',title:'मताधिकार',text:'दस्तावेज़ ने शिकायतें गिनाईं, फिर तय किया कि स्त्रियों को “मताधिकार का पवित्र अधिकार” है।',note:'मत देने का प्रश्न सुधारकों के बीच भी विवादित था, पर फ़्रेडरिक डगलस ने प्रस्ताव का ज़ोरदार समर्थन किया।'},{tag:'गठबंधन',title:'हस्ताक्षर और समर्थन',text:'दो दिन की चर्चा के बाद अड़सठ स्त्रियों और बत्तीस पुरुषों ने घोषणापत्र पर हस्ताक्षर किए।',note:'हस्ताक्षर ने निजी विश्वास को सार्वजनिक प्रतिबद्धता बना दिया।'}],question:'कौन-सा साक्ष्य इस दावे का सबसे अच्छा समर्थन करता है कि सम्मेलन ने मताधिकार को अमेरिकी संस्थापक आदर्शों से जोड़ा?',answers:['बैठक दो दिन चली।','घोषणापत्र ने “स्वतःस्पष्ट” और “समान बनाए गए” शब्दों की प्रतिध्वनि की।','सौ लोगों ने दस्तावेज़ पर हस्ताक्षर किए।'],hint:'किसी प्रसिद्ध संस्थापक दस्तावेज़ से ली गई भाषा खोजें।',explain:'स्वतंत्रता की घोषणा की सोची-समझी प्रतिध्वनि ने तर्क दिया कि समानता का उसका वादा स्त्रियों को भी शामिल करना चाहिए।'},
 {short:'गठबंधन चौराहा',title:'अनेक स्वर, साझा काम',place:'मंच, छापाखाने और क्लब भवन',artifact:'गठबंधन कुंजी',intro:'आंदोलन भाषणों, अख़बारों, सम्मेलनों, क्लबों और याचिकाओं से बढ़ता है। अलग-अलग नेता अलग अनुभव लाते हैं—और हमेशा सहमत नहीं होते।',facts:[{tag:'स्वर',title:'सोजर्नर ट्रुथ',text:'न्यूयॉर्क में दासता में जन्मीं ट्रुथ दास-उन्मूलन और स्त्री अधिकारों की सशक्त वक्ता बनीं।',note:'उनका 1851 का एक्रन भाषण भिन्न रूपों में बचा है—यह याद दिलाता है कि पूछें कि स्रोत किसने और कब दर्ज किया।'},{tag:'प्रेस',title:'फ़्रांसेस ई. डब्ल्यू. हार्पर',text:'लेखिका और व्याख्याता हार्पर ने ज़ोर दिया कि नस्ल, लिंग और आर्थिक न्याय अलग नहीं किए जा सकते।',note:'1866 में उन्होंने सुधारकों से कहा, “हम सब आपस में बँधे हैं।”'},{tag:'क्लब',title:'मैरी चर्च टेरेल',text:'टेरेल ने नेशनल एसोसिएशन ऑफ़ कलर्ड वीमेन की सह-स्थापना की, जिसका ध्येय था “चढ़ते हुए ऊपर उठाना”।',note:'अश्वेत स्त्रियों के क्लबों ने मताधिकार के लिए संगठन किया, और साथ ही आंदोलन के भीतर-बाहर की नस्लवाद का सामना किया।'}],question:'एक गठबंधन उन लोगों तक पहुँचना चाहता है जो बड़े सम्मेलनों से बाहर रखे गए। कौन-सी योजना आंदोलन की सबसे व्यापक रणनीतियाँ अपनाती है?',answers:['किसी एक प्रसिद्ध नेता के बोलने का इंतज़ार करें।','अख़बार निकालें, स्थानीय क्लब बनाएँ, वक्ताओं को बुलाएँ और याचिकाएँ फैलाएँ।','केवल राष्ट्रीय विधायकों को मनाने पर ध्यान दें।'],hint:'गठबंधन अनेक माध्यमों और स्थानीय संबंधों से बढ़ते हैं।',explain:'छपाई, क्लब, व्याख्यान-यात्राएँ और याचिकाएँ संगठनकर्ताओं को अलग-अलग समुदायों तक पहुँचने और टिकाऊ नेटवर्क बनाने देती थीं।'},
 {short:'राज्य रणनीति पथ',title:'मतपत्र तक अनेक रास्ते',place:'वायोमिंग से टेक्सस तक',artifact:'राज्य तारा',intro:'संघीय संशोधन से पहले संगठनकर्ताओं ने राज्य-स्तरीय रणनीतियाँ आज़माईं। रास्ता असमान रहा—कभी आगे, कभी किसी अड़चन के इर्द-गिर्द।',facts:[{tag:'पश्चिमी जीत',title:'वायोमिंग क्षेत्र, 1869',text:'वायोमिंग ने 1869 में स्त्रियों को मताधिकार दिया और 1890 में राज्य बनने पर उसे बनाए रखा।',note:'पश्चिमी जीतों ने प्रमाण दिया कि स्त्रियों का मतदान व्यवहार में काम करता है।'},{tag:'राज्य अभियान',title:'याचिकाएँ और जनमत-संग्रह',text:'संगठनकर्ताओं ने हस्ताक्षर जुटाए, विधायकों पर दबाव डाला और राज्यव्यापी जनमत-संग्रहों में अभियान चलाया।',note:'राज्य-दर-राज्य काम ने स्थानीय संगठन-कौशल बनाया, तब भी जब कोई जनमत-संग्रह हार गया।'},{tag:'टेक्सस',title:'प्राइमरी मताधिकार, 1918',text:'टेक्सस की स्त्रियों को प्राइमरी चुनावों में मत देने का अधिकार मिला—बशर्ते वे मतदान दिवस से कम से कम 15 दिन पहले पंजीकरण कराएँ।',note:'मिनी फ़िशर कनिंघम और हज़ारों स्वयंसेविकाओं ने तेज़ पंजीकरण अभियान चलाया।'}],question:'एक टेक्सस संगठनकर्ता के पास 1918 की प्राइमरी से पहले कुछ ही सप्ताह हैं। अभियान को किसे प्राथमिकता देनी चाहिए?',answers:['संघीय संशोधन का इंतज़ार करें।','तुरंत पंजीकरण अभियान चलाएँ और 15-दिन की समय-सीमा स्पष्ट रूप से समझाएँ।','अभियान को वायोमिंग ले जाएँ।'],hint:'काग़ज़ पर मिला अधिकार तभी मायने रखता है जब लोग समय रहते पहुँच के नियम पूरे कर सकें।',explain:'टेक्सस के संगठनकर्ताओं ने कानूनी जीत के साथ तत्काल स्थानीय पंजीकरण कार्य जोड़ा ताकि पात्र स्त्रियाँ सचमुच मत डाल सकें।'},
 {short:'अनुसमर्थन दौड़',title:'छत्तीस राज्य',place:'कांग्रेस से टेनेसी तक',artifact:'19वें संशोधन की मुहर',intro:'कांग्रेस ने संशोधन पारित कर दिया है। अब तीन-चौथाई राज्यों को इसका अनुसमर्थन करना होगा। संवैधानिक रास्ते का अनुसरण करें—फिर टेनेसी का निर्णायक मत खोलें।',facts:[{tag:'चरण 1',title:'कांग्रेस प्रस्ताव करती है',text:'4 जून 1919 को सीनेट ने प्रस्तावित संशोधन पारित करने में प्रतिनिधि सभा का साथ दिया।',note:'प्रस्ताव अनुसमर्थन नहीं है। कांग्रेस ने पाठ राज्यों को भेजा।'},{tag:'चरण 2',title:'राज्य तय करते हैं',text:'1920 की गर्मियों तक पैंतीस राज्य अनुसमर्थन कर चुके थे। एक और चाहिए था।',note:'कार्यकर्ताओं ने यात्राएँ कीं, पत्र लिखे, पैरवी की और देश भर में मतों का हिसाब रखा।'},{tag:'चरण 3',title:'टेनेसी, 1920',text:'18 अगस्त को टेनेसी अनुसमर्थन करने वाला 36वाँ राज्य बना। 26 अगस्त को प्रमाणन हुआ।',note:'राज्य-सदन का मत बेहद नज़दीकी था। वर्षों के संगठन से एक संवैधानिक मील का पत्थर निकला।'}],question:'अंतिम संवैधानिक चरणों को सही क्रम में रखें।',answers:['प्रमाणन → राज्य अनुसमर्थन → कांग्रेस का प्रस्ताव','कांग्रेस का प्रस्ताव → 36 राज्यों का अनुसमर्थन → प्रमाणन','राज्य अनुसमर्थन → प्रमाणन → कांग्रेस का प्रस्ताव'],hint:'कांग्रेस प्रस्ताव करती है; राज्य अनुसमर्थन करते हैं; संघीय सरकार प्रमाणित करती है।',explain:'संशोधन कांग्रेस के प्रस्ताव से, तीन-चौथाई राज्यों की मंज़ूरी होते हुए, संघीय प्रमाणन तक पहुँचा।'},
 {short:'समानता द्वार',title:'एक मील का पत्थर, अंत नहीं',place:'अधूरा रास्ता',artifact:'समानता मशाल',intro:'19वें संशोधन ने लिंग के आधार पर मतदान में भेदभाव रोका। पर अन्य बाधाएँ अब भी बहुत नागरिकों का रास्ता रोकती थीं। इतिहास हमसे कहता है कि प्रगति और अधूरा काम—दोनों को साथ थामें।',facts:[{tag:'बाधा',title:'नागरिकता प्रतिबंध',text:'बहुत-से मूल अमेरिकियों को 1924 तक अमेरिकी नागरिकता नहीं दी गई; भेदभावपूर्ण राज्य कानून उसके बाद भी चलते रहे।',note:'नागरिकता ने अपने आप पंजीकरण या मतपत्र तक पहुँच की गारंटी नहीं दी।'},{tag:'बाधा',title:'जिम क्रो और श्वेत प्राइमरी',text:'मतदान कर, साक्षरता परीक्षाएँ, हिंसा और पूर्ण-श्वेत प्राइमरी ने अश्वेत मतदान को दबाया, विशेषकर दक्षिण में।',note:'अश्वेत कार्यकर्ताओं ने दशकों तक अदालतों, समुदायों और कांग्रेस में इन व्यवस्थाओं को चुनौती दी।'},{tag:'प्रतिक्रिया',title:'मताधिकार अधिनियम, 1965',text:'इस अधिनियम ने मतदान में नस्लीय भेदभाव के विरुद्ध संघीय सरकार को मज़बूत औज़ार दिए।',note:'कानूनों, अदालती फ़ैसलों, संगठन और जन-भागीदारी से पहुँच बदलती रही है।'}],question:'साक्ष्य किस निष्कर्ष का सबसे अच्छा समर्थन करते हैं?',answers:['19वें संशोधन ने तुरंत हर अमेरिकी वयस्क को समान मतदान पहुँच की गारंटी दे दी।','19वाँ संशोधन महत्वहीन था क्योंकि बाधाएँ बनी रहीं।','19वाँ संशोधन एक बड़ा संवैधानिक मील का पत्थर था, जबकि नागरिकता और नस्ल की बाधाओं ने मतदान पहुँच को अधूरा छोड़ा।'],hint:'मज़बूत ऐतिहासिक व्याख्याएँ वास्तविक बदलाव और वास्तविक सीमाएँ—दोनों को पहचान सकती हैं।',explain:'संशोधन ने संविधान बदला, पर उसने नस्ल, नागरिकता या भेदभावपूर्ण प्रशासन पर आधारित बाधाएँ नहीं मिटाईं।'}
];
levelText.ur=[
 {short:'اعلان ہال',title:'ایک اعلان تشکیل پاتا ہے',place:'سینیکا فالز، نیو یارک',artifact:'آواز کا بیج',intro:'اس اجلاس گاہ میں عام لوگ ایک غیر معمولی کام کر رہے ہیں: ناانصافی کو سرِعام نام دینا۔ وہ شواہد جمع کریں جن سے انہوں نے اپنی بات رکھی۔',facts:[{tag:'بنیادی ماخذ',title:'اعلانِ جذبات',text:'”ہم ان سچائیوں کو بدیہی مانتے ہیں: کہ تمام مرد اور عورتیں برابر پیدا کیے گئے ہیں۔“',note:'لکھنے والوں نے جان بوجھ کر اعلانِ آزادی کی بازگشت کی تاکہ عورتوں کے حقوق کو قوم کے بنیادی نصب العین سے جوڑا جا سکے۔'},{tag:'مطالبہ',title:'حقِ رائے دہی',text:'دستاویز نے شکایات گنوائیں، پھر طے کیا کہ عورتوں کو ”حقِ رائے دہی کا مقدس حق“ حاصل ہے۔',note:'ووٹ کا معاملہ اصلاح پسندوں میں بھی متنازع تھا، مگر فریڈرک ڈگلس نے قرارداد کی بھرپور حمایت کی۔'},{tag:'اتحاد',title:'دستخط اور حمایت',text:'دو دن کے مباحثے کے بعد اڑسٹھ عورتوں اور بتیس مردوں نے اعلان پر دستخط کیے۔',note:'دستخط نے ایک نجی یقین کو عوامی عہد میں بدل دیا۔'}],question:'کون سی شہادت اس دعوے کی سب سے بہتر تائید کرتی ہے کہ کنونشن نے حقِ رائے دہی کو امریکی بنیادی نصب العین سے جوڑا؟',answers:['اجلاس دو دن جاری رہا۔','اعلان نے ”بدیہی“ اور ”برابر پیدا کیے گئے“ کے الفاظ دہرائے۔','سو افراد نے دستاویز پر دستخط کیے۔'],hint:'کسی مشہور بنیادی دستاویز سے لی گئی زبان تلاش کریں۔',explain:'اعلانِ آزادی کی سوچی سمجھی بازگشت نے دلیل دی کہ برابری کا اس کا وعدہ عورتوں کو بھی شامل کرنا چاہیے۔'},
 {short:'اتحاد کا چوراہا',title:'بہت سی آوازیں، مشترکہ کام',place:'منبر، چھاپہ خانے اور کلب',artifact:'اتحاد کی کنجی',intro:'تحریک تقریروں، اخباروں، کنونشنوں، کلبوں اور درخواستوں سے بڑھتی ہے۔ مختلف رہنما مختلف تجربات لاتے ہیں—اور ہمیشہ متفق نہیں ہوتے۔',facts:[{tag:'آواز',title:'سوجرنر ٹروتھ',text:'نیو یارک میں غلامی میں پیدا ہونے والی ٹروتھ غلامی کے خاتمے اور عورتوں کے حقوق کی طاقتور مقرر بنیں۔',note:'ان کی 1851 کی ایکرن تقریر مختلف روایتوں میں محفوظ ہے—یاد دہانی کہ پوچھیں ماخذ کس نے اور کب لکھا۔'},{tag:'پریس',title:'فرانسس ای. ڈبلیو. ہارپر',text:'ادیبہ اور مقررہ ہارپر نے اصرار کیا کہ نسل، صنف اور معاشی انصاف الگ نہیں کیے جا سکتے۔',note:'1866 میں انہوں نے اصلاح پسندوں سے کہا، ”ہم سب ایک دوسرے سے بندھے ہوئے ہیں۔“'},{tag:'کلب',title:'میری چرچ ٹیرل',text:'ٹیرل نے نیشنل ایسوسی ایشن آف کلرڈ ویمن کی بنیاد رکھنے میں مدد دی، جس کا نصب العین تھا ”چڑھتے ہوئے اٹھانا“۔',note:'سیاہ فام عورتوں کے کلبوں نے حقِ رائے دہی کے لیے تنظیم کی، اور ساتھ ہی تحریک کے اندر اور باہر نسل پرستی کا سامنا کیا۔'}],question:'ایک اتحاد ان لوگوں تک پہنچنا چاہتا ہے جو بڑے کنونشنوں سے باہر رکھے گئے۔ کون سا منصوبہ تحریک کی وسیع ترین حکمتِ عملی استعمال کرتا ہے؟',answers:['کسی ایک مشہور رہنما کے بولنے کا انتظار کریں۔','اخبار نکالیں، مقامی کلب بنائیں، مقررین بلائیں اور درخواستیں پھیلائیں۔','صرف قومی قانون سازوں کو قائل کرنے پر توجہ دیں۔'],hint:'اتحاد بہت سے راستوں اور مقامی تعلقات سے بڑھتے ہیں۔',explain:'چھپائی، کلب، تقریری دورے اور درخواستیں منتظمین کو الگ الگ برادریوں تک پہنچنے اور پائیدار نیٹ ورک بنانے دیتی تھیں۔'},
 {short:'ریاستی حکمتِ عملی کا راستہ',title:'ووٹ تک بہت سے راستے',place:'وائیومنگ سے ٹیکساس تک',artifact:'ریاستی ستارہ',intro:'وفاقی ترمیم سے پہلے منتظمین نے ریاستی حکمتِ عملی آزمائی۔ راستہ ناہموار رہا—کبھی آگے، کبھی کسی رکاوٹ کے گرد۔',facts:[{tag:'مغربی کامیابی',title:'علاقہ وائیومنگ، 1869',text:'وائیومنگ نے 1869 میں عورتوں کو ووٹ کا حق دیا اور 1890 میں ریاست بننے پر اسے برقرار رکھا۔',note:'مغربی کامیابیوں نے ثبوت دیا کہ عورتوں کا ووٹ عملاً کارگر ہے۔'},{tag:'ریاستی مہم',title:'درخواستیں اور ریفرنڈم',text:'منتظمین نے دستخط جمع کیے، قانون سازوں پر دباؤ ڈالا اور ریاست گیر ریفرنڈموں میں مہم چلائی۔',note:'ریاست در ریاست کام نے مقامی تنظیمی مہارت پیدا کی، تب بھی جب کوئی ریفرنڈم ناکام ہوا۔'},{tag:'ٹیکساس',title:'پرائمری میں حقِ رائے دہی، 1918',text:'ٹیکساس کی عورتوں نے پرائمری انتخابات میں ووٹ کا حق جیتا—بشرطیکہ وہ انتخاب سے کم از کم 15 دن پہلے رجسٹر کرائیں۔',note:'مِنی فشر کننگھم اور ہزاروں رضاکاروں نے تیز رفتار رجسٹریشن مہم چلائی۔'}],question:'ایک ٹیکساس منتظم کے پاس 1918 کی پرائمری سے پہلے چند ہی ہفتے ہیں۔ مہم کو کسے ترجیح دینی چاہیے؟',answers:['وفاقی ترمیم کا انتظار کریں۔','فوری رجسٹریشن مہم چلائیں اور 15 دن کی مہلت واضح طور پر سمجھائیں۔','مہم وائیومنگ منتقل کر دیں۔'],hint:'کاغذ پر ملا حق تبھی معنی رکھتا ہے جب لوگ وقت پر رسائی کے اصول پورے کر سکیں۔',explain:'ٹیکساس کے منتظمین نے قانونی کامیابی کے ساتھ فوری مقامی رجسٹریشن کا کام جوڑا تاکہ اہل عورتیں واقعی ووٹ ڈال سکیں۔'},
 {short:'توثیق کی دوڑ',title:'چھتیس ریاستیں',place:'کانگریس سے ٹینیسی تک',artifact:'انیسویں ترمیم کی مہر',intro:'کانگریس ترمیم منظور کر چکی ہے۔ اب تین چوتھائی ریاستوں کو اس کی توثیق کرنی ہوگی۔ آئینی راستے پر چلیں—پھر ٹینیسی کا فیصلہ کن ووٹ کھولیں۔',facts:[{tag:'مرحلہ 1',title:'کانگریس تجویز کرتی ہے',text:'4 جون 1919 کو سینیٹ نے مجوزہ ترمیم منظور کرنے میں ایوانِ نمائندگان کا ساتھ دیا۔',note:'تجویز توثیق نہیں ہوتی۔ کانگریس نے متن ریاستوں کو بھیجا۔'},{tag:'مرحلہ 2',title:'ریاستیں فیصلہ کرتی ہیں',text:'1920 کے موسمِ گرما تک پینتیس ریاستیں توثیق کر چکی تھیں۔ ایک اور درکار تھی۔',note:'کارکنوں نے سفر کیے، خط لکھے، پیروی کی اور ملک بھر میں ووٹوں کا حساب رکھا۔'},{tag:'مرحلہ 3',title:'ٹینیسی، 1920',text:'18 اگست کو ٹینیسی توثیق کرنے والی 36ویں ریاست بنی۔ 26 اگست کو تصدیق ہوئی۔',note:'ریاستی ایوان کا ووٹ نہایت قریب تھا۔ برسوں کی تنظیم سے ایک آئینی سنگِ میل نکلا۔'}],question:'آخری آئینی مراحل کو درست ترتیب میں رکھیں۔',answers:['تصدیق ← ریاستی توثیق ← کانگریس کی تجویز','کانگریس کی تجویز ← 36 ریاستوں کی توثیق ← تصدیق','ریاستی توثیق ← تصدیق ← کانگریس کی تجویز'],hint:'کانگریس تجویز کرتی ہے؛ ریاستیں توثیق کرتی ہیں؛ وفاقی حکومت تصدیق کرتی ہے۔',explain:'ترمیم کانگریس کی تجویز سے، تین چوتھائی ریاستوں کی منظوری سے ہوتی ہوئی، وفاقی تصدیق تک پہنچی۔'},
 {short:'برابری کا دروازہ',title:'ایک سنگِ میل، انجام نہیں',place:'ادھورا راستہ',artifact:'برابری کی مشعل',intro:'انیسویں ترمیم نے جنس کی بنیاد پر ووٹ میں امتیاز روکا۔ مگر دوسری رکاوٹیں اب بھی بہت سے شہریوں کا راستہ روکتی تھیں۔ تاریخ ہم سے کہتی ہے کہ پیش رفت اور ادھورا کام—دونوں ساتھ تھامیں۔',facts:[{tag:'رکاوٹ',title:'شہریت کی پابندیاں',text:'بہت سے مقامی امریکیوں کو 1924 تک امریکی شہریت نہ دی گئی؛ امتیازی ریاستی قوانین اس کے بعد بھی جاری رہے۔',note:'شہریت نے خود بخود رجسٹریشن یا ووٹ تک رسائی کی ضمانت نہیں دی۔'},{tag:'رکاوٹ',title:'جم کرو اور سفید پرائمری',text:'ووٹ ٹیکس، خواندگی کے امتحان، تشدد اور صرف سفید فام پرائمری نے سیاہ فام ووٹ کو دبایا، خاص کر جنوب میں۔',note:'سیاہ فام کارکنوں نے دہائیوں تک عدالتوں، برادریوں اور کانگریس میں ان نظاموں کو چیلنج کیا۔'},{tag:'ردِعمل',title:'ووٹنگ رائٹس ایکٹ، 1965',text:'اس قانون نے ووٹ میں نسلی امتیاز کے خلاف وفاقی حکومت کو مضبوط اوزار دیے۔',note:'قوانین، عدالتی فیصلوں، تنظیم اور عوامی شرکت سے رسائی بدلتی رہی ہے۔'}],question:'شواہد کس نتیجے کی سب سے بہتر تائید کرتے ہیں؟',answers:['انیسویں ترمیم نے فوراً ہر امریکی بالغ کو ووٹ تک برابر رسائی کی ضمانت دے دی۔','انیسویں ترمیم غیر اہم تھی کیونکہ رکاوٹیں باقی رہیں۔','انیسویں ترمیم ایک بڑا آئینی سنگِ میل تھی، جبکہ شہریت اور نسل کی رکاوٹوں نے ووٹ تک رسائی ادھوری چھوڑی۔'],hint:'مضبوط تاریخی تشریحات حقیقی تبدیلی اور حقیقی حدود—دونوں کو تسلیم کر سکتی ہیں۔',explain:'ترمیم نے آئین بدلا، مگر اس نے نسل، شہریت یا امتیازی انتظامیہ پر مبنی رکاوٹیں نہیں مٹائیں۔'}
];
